{"command": "uv run --quiet --with pandas --with numpy python - <<'PY'
import pandas as pd, numpy as np
df = pd.read_csv('measurements.csv')
for (mat, sp), g in df.groupby(['material','specimen']):
    for hi in [0.0020, 0.0018, 0.0016, 0.0014]:
        d = g[g.strain <= hi+1e-12]
        p = np.polyfit(d.strain, d.stress_mpa, 1)
        pred = np.polyval(p, d.strain)
        r2 = 1 - ((d.stress_mpa-pred)**2).sum()/((d.stress_mpa-d.stress_mpa.mean())**2).sum()
        if hi==0.0020:
            print(f"{sp:5s} full E={p[0]/1000:7.2f} GPa b={p[1]:6.2f} R2={r2:.5f}", end='')
        else:
            print(f" | <={hi:.4f} E={p[0]/1000:7.2f}", end='')
    print()
PY"}

